function HolidayCalendarPanel() {
    const [holidays, setHolidays] = useState([]);
    const [loading, setLoading] = useState(false);
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

    useEffect(() => {
        fetchHolidays();
    }, []);

    const fetchHolidays = async () => {
        setLoading(true);
        try {
            const res = await api.get('/holidays');
            setHolidays(Array.isArray(res.data) ? res.data : []);
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const holidaysByMonth = {};
    months.forEach((m, idx) => {
        holidaysByMonth[idx] = [];
    });

    holidays.forEach(h => {
        if (h.date) {
            const start = new Date(h.date);
            const end = h.endDate ? new Date(h.endDate) : start;

            const uniqueMonths = new Set();
            for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
                uniqueMonths.add(d.getMonth());
            }

            uniqueMonths.forEach(m => {
                if (holidaysByMonth[m]) {
                    holidaysByMonth[m].push(h);
                }
            });
        }
    });

    return (
        <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
            <div>
                <h3 className="font-extrabold text-slate-800 text-sm uppercase tracking-tight">Yearly Holiday Calendar</h3>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Interactive calendar overview by month</p>
            </div>

            {loading ? (
                <div className="py-20 text-center flex flex-col items-center justify-center gap-3">
                    <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Generating calendar...</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                    {months.map((month, idx) => {
                        const monthHolidays = holidaysByMonth[idx] || [];
                        return (
                            <div key={idx} className="bg-white border border-slate-200 rounded-2xl p-4 shadow-sm space-y-3 flex flex-col justify-between min-h-[160px]">
                                <div>
                                    <div className="flex justify-between items-center border-b border-slate-100 pb-1.5 mb-2">
                                        <h4 className="font-black text-slate-800 text-xs uppercase tracking-wider">{month}</h4>
                                        <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-lg">{monthHolidays.length} Holidays</span>
                                    </div>
                                    {monthHolidays.length === 0 ? (
                                        <p className="text-[10px] text-slate-400 italic">No holidays in this month</p>
                                    ) : (
                                        <div className="space-y-1.5 max-h-[100px] overflow-y-auto pr-1">
                                            {monthHolidays.map(h => {
                                                const startDate = new Date(h.date);
                                                const endDate = h.endDate ? new Date(h.endDate) : null;
                                                const d = startDate.getDate();

                                                const isMultiDay = endDate && endDate.getDate() !== startDate.getDate();
                                                const rangeText = isMultiDay 
                                                    ? ` (${startDate.getDate()} ${startDate.toLocaleDateString('en-US', {month: 'short'})} - ${endDate.getDate()} ${endDate.toLocaleDateString('en-US', {month: 'short'})})`
                                                    : '';
                                                return (
                                                    <div key={h._id} className="flex gap-2 items-center text-[11px] font-bold text-slate-700">
                                                        <span className="w-6 h-6 rounded-lg bg-indigo-50 border border-indigo-150 text-indigo-600 flex items-center justify-center shrink-0 text-[10px] font-extrabold">{d}</span>
                                                        <div className="min-w-0">
                                                            <div className="truncate text-slate-800" title={`${h.name}${rangeText}`}>{h.name}{rangeText}</div>
                                                            <div className="text-[8px] font-black text-slate-400 uppercase tracking-wider leading-none mt-0.5">{h.type}</div>
                                                        </div>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

