        if (cleanType === 'EARNED LEAVE') return 'EL';
        if (cleanType === 'PRIVILEGE LEAVE') return 'PL';
        return cleanType;
    };

    if (!name && (!rules || rules.length === 0)) return '';

    let prefix = 'PL';

    if (rules && rules.length > 0) {
        const hasEL = rules.find(r => ['EL', 'PL', 'EARNED LEAVE', 'PRIVILEGE LEAVE'].includes(r.leaveType?.toUpperCase()));
