        }
    }

    prefix = prefix.replace(/[^a-zA-Z0-9]/g, '').toUpperCase().slice(0, 6);
    if (!prefix) prefix = 'PL';

    let nextNum = 1;
    const regex = new RegExp(`^${prefix}-(\\d+)$`, 'i');

    if (existingPolicies && existingPolicies.length > 0) {
        existingPolicies.forEach(p => {
            if (p.policyId) {
