function EncashmentPanel() {
    const [config, setConfig] = useState({
        allowed: false,
        leaveType: 'EL',
        formula: 'Basic / 30',
        minBalanceRetain: 15,
        maxEncashableDays: 10,
        taxRule: 'Exempt up to 3 Lakhs'
    });
    const [requests, setRequests] = useState([]);
    const [loading, setLoading] = useState(false);
    const [saving, setSaving] = useState(false);
    const [processingId, setProcessingId] = useState(null);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [configRes, requestsRes] = await Promise.all([
                api.get('/hr/leaves/encashment/config'),
                api.get('/hr/leaves/encashment/requests')
            ]);
            if (configRes.data) {
                setConfig(configRes.data);
            }
            if (requestsRes.data) {
                setRequests(requestsRes.data);
            }
        } catch (error) {
            console.error('[EncashmentPanel] Fetch error:', error);
            showToast('error', 'Error', 'Failed to load leave encashment details.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchData();
    }, []);

    const handleSaveConfig = async () => {
        setSaving(true);
        try {
            await api.post('/hr/leaves/encashment/config', config);
            showToast('success', 'Saved', 'Configuration saved successfully.');
        } catch (error) {
            console.error('[EncashmentPanel] Save error:', error);
            showToast('error', 'Error', 'Failed to save configuration.');
        } finally {
            setSaving(false);
        }
    };

    const handleApprove = async (requestId) => {
        const remark = prompt('Enter approval remark (optional):') || '';
        setProcessingId(requestId);
        try {
            await api.post(`/hr/leaves/encashment/requests/${requestId}/approve`, { adminRemark: remark });
            showToast('success', 'Approved', 'Leave encashment approved successfully.');
            await fetchData();
        } catch (error) {
            console.error('[EncashmentPanel] Approve error:', error);
            showToast('error', 'Error', error?.response?.data?.error || 'Failed to approve request.');
        } finally {
            setProcessingId(null);
        }
    };

    const handleReject = async (requestId) => {
        const remark = prompt('Enter rejection remark (required):');
        if (remark === null) return;
        if (!remark.trim()) {
            showToast('warning', 'Remark Required', 'Rejection remark is required.');
            return;
        }
        setProcessingId(requestId);
        try {
            await api.post(`/hr/leaves/encashment/requests/${requestId}/reject`, { adminRemark: remark });
            showToast('success', 'Rejected', 'Leave encashment request rejected.');
            await fetchData();
        } catch (error) {
            console.error('[EncashmentPanel] Reject error:', error);
            showToast('error', 'Error', error?.response?.data?.error || 'Failed to reject request.');
        } finally {
            setProcessingId(null);
        }
    };

    const pendingRequests = requests.filter(r => r.status === 'Pending');
    const processedRequests = requests.filter(r => r.status !== 'Pending');

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-500">
            {/* Rule Config */}
            <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-sm space-y-4 h-fit">
                <div>
                    <h3 className="font-extrabold text-slate-800 text-sm uppercase tracking-tight">Encashment Policy Config</h3>
                </div>

                <div className="space-y-3.5">
                    {/* Allowed Toggle */}
                    <div className="flex justify-between items-center bg-slate-50 p-3 rounded-xl border border-slate-150">
                        <span className="text-xs font-bold text-slate-700">Encashment Buyout Allowed</span>
                        <button
                            onClick={() => setConfig(prev => ({ ...prev, allowed: !prev.allowed }))}
                            className={`relative w-8 h-4 rounded-full transition-all duration-300 outline-none ${config.allowed ? 'bg-indigo-500' : 'bg-slate-200'}`}
                        >
                            <div className={`absolute top-0.5 w-3 h-3 bg-white rounded-full shadow-sm transition-all duration-300 ${config.allowed ? 'left-[18px]' : 'left-0.5'}`} />
                        </button>
                    </div>

                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-tight">Buyout Leave Type</label>
                        <select
                            value={config.leaveType}
                            onChange={e => setConfig(prev => ({ ...prev, leaveType: e.target.value }))}
                            className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold text-slate-700 outline-none"
                        >
                            <option value="EL">EL (Earned Leave)</option>
                            <option value="PL">PL (Privilege Leave)</option>
                        </select>
                    </div>

                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-tight">Calculation Formula</label>
                        <select
                            value={config.formula}
                            onChange={e => setConfig(prev => ({ ...prev, formula: e.target.value }))}
                            className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold text-slate-700 outline-none"
                        >
                            <option value="Basic / 30">Basic Salary / 30 * Buyout Days</option>
                            <option value="Gross / 30">Gross Salary / 30 * Buyout Days</option>
                        </select>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        <div className="space-y-1">
                            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-tight">Min Retained Balance</label>
                            <input
                                type="number"
                                value={config.minBalanceRetain}
                                onChange={e => setConfig(prev => ({ ...prev, minBalanceRetain: parseInt(e.target.value) || 0 }))}
                                className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold text-slate-700 outline-none"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-tight">Max Buyout / Yr</label>
                            <input
                                type="number"
                                value={config.maxEncashableDays}
                                onChange={e => setConfig(prev => ({ ...prev, maxEncashableDays: parseInt(e.target.value) || 0 }))}
                                className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold text-slate-700 outline-none"
                            />
                        </div>
                    </div>

                    <div className="space-y-1">
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-tight">Tax Rule / Exemption</label>
                        <select
                            value={config.taxRule}
                            onChange={e => setConfig(prev => ({ ...prev, taxRule: e.target.value }))}
                            className="w-full h-10 px-3 bg-slate-50 border border-slate-200 rounded-lg text-xs font-bold text-slate-700 outline-none"
                        >
                            <option value="Exempt up to 3 Lakhs">Exempt up to ₹3,00,000 (Section 10(10AA))</option>
                            <option value="Fully Taxable">Fully Taxable</option>
                        </select>
                    </div>

                    <button
                        onClick={handleSaveConfig}
                        disabled={saving}
                        className="w-full py-2.5 bg-slate-900 hover:bg-black text-white text-[10px] font-black uppercase tracking-widest rounded-xl transition-all shadow-md flex justify-center disabled:opacity-50"
                    >
                        {saving ? 'Saving...' : 'Save Configuration'}
                    </button>
                </div>
            </div>

            {/* Buyout Requests and History */}
            <div className="lg:col-span-2 space-y-6">
                {/* Pending Requests */}
                <div className="bg-white border border-slate-200 rounded-2xl p-5 shadow-sm space-y-4">
                    <h3 className="font-extrabold text-slate-800 text-sm uppercase tracking-tight">Pending Encashment Requests</h3>
                    <div className="overflow-x-auto border border-slate-100 rounded-xl">
                        <table className="w-full text-left border-collapse text-xs">
                            <thead>
                                <tr className="bg-slate-50 border-b border-slate-150">
                                    <th className="px-4 py-3 text-[9px] font-black text-slate-450 uppercase tracking-widest">Employee</th>
                                    <th className="px-4 py-3 text-[9px] font-black text-slate-450 uppercase tracking-widest text-center">Days</th>
                                    <th className="px-4 py-3 text-[9px] font-black text-slate-450 uppercase tracking-widest text-right">Estimated Payout</th>
                                    <th className="px-4 py-3 text-[9px] font-black text-slate-450 uppercase tracking-widest">Reason</th>
                                    <th className="px-4 py-3 text-[9px] font-black text-slate-450 uppercase tracking-widest text-center">Actions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 font-bold text-slate-700">
                                {pendingRequests.length === 0 ? (
                                    <tr>
                                        <td colSpan="5" className="px-4 py-8 text-center text-slate-400 font-medium">No pending requests found.</td>
                                    </tr>
                                ) : (
                                    pendingRequests.map(item => {
                                        const emp = item.employee || {};
                                        const name = emp.firstName ? `${emp.firstName} ${emp.lastName || ''}` : 'Employee';
                                        return (
                                            <tr key={item._id} className="hover:bg-slate-50/50">
                                                <td className="px-4 py-3">
                                                    <div className="font-extrabold text-slate-900">{name}</div>
                                                    <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{emp.employeeId || '—'}</div>
                                                </td>
                                                <td className="px-4 py-3 text-center font-mono">{item.requestedDays} Days</td>
                                                <td className="px-4 py-3 text-right font-mono text-slate-900">₹{item.payoutAmount.toLocaleString()}</td>
                                                <td className="px-4 py-3 font-normal text-slate-500 max-w-[120px] truncate" title={item.reason}>{item.reason || '—'}</td>
